1	import type { Request, RequestHandler } from "express";
2	import type { IncomingHttpHeaders } from "node:http";
3	import { betterAuth } from "better-auth";
4	import { drizzleAdapter } from "better-auth/adapters/drizzle";
5	import { toNodeHandler } from "better-auth/node";
6	import type { Db } from "@paperclipai/db";
7	import {
8	  authAccounts,
9	  authSessions,
10	  authUsers,
11	  authVerifications,
12	} from "@paperclipai/db";
13	import type { Config } from "../config.js";
14	import { resolvePaperclipInstanceId } from "../home-paths.js";
15	
16	export type BetterAuthSessionUser = {
17	  id: string;
18	  email?: string | null;
19	  name?: string | null;
20	};
21	
22	export type BetterAuthSessionResult = {
23	  session: { id: string; userId: string } | null;
24	  user: BetterAuthSessionUser | null;
25	};
26	
27	type BetterAuthInstance = ReturnType<typeof betterAuth>;
28	
29	const AUTH_COOKIE_PREFIX_FALLBACK = "default";
30	const AUTH_COOKIE_PREFIX_INVALID_SEGMENTS_RE = /[^a-zA-Z0-9_-]+/g;
31	
32	export function deriveAuthCookiePrefix(instanceId = resolvePaperclipInstanceId()): string {
33	  const scopedInstanceId = instanceId
34	    .trim()
35	    .replace(AUTH_COOKIE_PREFIX_INVALID_SEGMENTS_RE, "-")
36	    .replace(/^-+|-+$/g, "") || AUTH_COOKIE_PREFIX_FALLBACK;
37	  return `paperclip-${scopedInstanceId}`;
38	}
39	
40	export function buildBetterAuthAdvancedOptions(input: { disableSecureCookies: boolean }) {
41	  return {
42	    cookiePrefix: deriveAuthCookiePrefix(),
43	    ...(input.disableSecureCookies ? { useSecureCookies: false } : {}),
44	  };
45	}
