47	function headersFromNodeHeaders(rawHeaders: IncomingHttpHeaders): Headers {
48	  const headers = new Headers();
49	  for (const [key, raw] of Object.entries(rawHeaders)) {
50	    if (!raw) continue;
51	    if (Array.isArray(raw)) {
52	      for (const value of raw) headers.append(key, value);
53	      continue;
54	    }
55	    headers.set(key, raw);
56	  }
57	  return headers;
58	}
59	
60	function headersFromExpressRequest(req: Request): Headers {
61	  return headersFromNodeHeaders(req.headers);
62	}
63	
64	export function deriveAuthTrustedOrigins(config: Config, opts?: { listenPort?: number }): string[] {
65	  const baseUrl = config.authBaseUrlMode === "explicit" ? config.authPublicBaseUrl : undefined;
66	  const trustedOrigins = new Set<string>();
67	
68	  if (baseUrl) {
69	    try {
70	      trustedOrigins.add(new URL(baseUrl).origin);
71	    } catch {
72	      // Better Auth will surface invalid base URL separately.
73	    }
74	  }
75	  if (config.deploymentMode === "authenticated") {
76	    const port = opts?.listenPort ?? config.port;
77	    const needsPortVariants = port !== 80 && port !== 443;
78	    for (const hostname of config.allowedHostnames) {
79	      const trimmed = hostname.trim().toLowerCase();
80	      if (!trimmed) continue;
81	      trustedOrigins.add(`https://${trimmed}`);
82	      trustedOrigins.add(`http://${trimmed}`);
83	      if (needsPortVariants) {
84	        trustedOrigins.add(`https://${trimmed}:${port}`);
85	        trustedOrigins.add(`http://${trimmed}:${port}`);
86	      }
87	    }
88	  }
89	
90	  return Array.from(trustedOrigins);
91	}
