93	export function createBetterAuthInstance(db: Db, config: Config, trustedOrigins: string[]): BetterAuthInstance {
94	  const baseUrl = config.authBaseUrlMode === "explicit" ? config.authPublicBaseUrl : undefined;
95	  const secret = process.env.BETTER_AUTH_SECRET ?? process.env.PAPERCLIP_AGENT_JWT_SECRET;
96	  if (!secret) {
97	    throw new Error(
98	      "BETTER_AUTH_SECRET (or PAPERCLIP_AGENT_JWT_SECRET) must be set. " +
99	      "For local development, set BETTER_AUTH_SECRET=paperclip-dev-secret in your .env file.",
100	    );
101	  }
102	  const publicUrl = process.env.PAPERCLIP_PUBLIC_URL ?? baseUrl;
103	  const isHttpOnly = publicUrl ? publicUrl.startsWith("http://") : false;
104	
105	  const authConfig = {
106	    baseURL: baseUrl,
107	    secret,
108	    trustedOrigins,
109	    database: drizzleAdapter(db, {
110	      provider: "pg",
111	      schema: {
112	        user: authUsers,
113	        session: authSessions,
114	        account: authAccounts,
115	        verification: authVerifications,
116	      },
117	    }),
118	    emailAndPassword: {
119	      enabled: true,
120	      requireEmailVerification: false,
121	      disableSignUp: config.authDisableSignUp,
122	    },
123	    advanced: buildBetterAuthAdvancedOptions({ disableSecureCookies: isHttpOnly }),
124	  };
125	
126	  if (!baseUrl) {
127	    delete (authConfig as { baseURL?: string }).baseURL;
128	  }
129	
130	  return betterAuth(authConfig);
131	}
