133	export function createBetterAuthHandler(auth: BetterAuthInstance): RequestHandler {
134	  const handler = toNodeHandler(auth);
135	  return (req, res, next) => {
136	    void Promise.resolve(handler(req, res)).catch(next);
137	  };
138	}
