140	export async function resolveBetterAuthSessionFromHeaders(
141	  auth: BetterAuthInstance,
142	  headers: Headers,
143	): Promise<BetterAuthSessionResult | null> {
144	  const api = (auth as unknown as { api?: { getSession?: (input: unknown) => Promise<unknown> } }).api;
145	  if (!api?.getSession) return null;
146	
147	  const sessionValue = await api.getSession({
148	    headers,
149	  });
150	  if (!sessionValue || typeof sessionValue !== "object") return null;
151	
152	  const value = sessionValue as {
153	    session?: { id?: string; userId?: string } | null;
154	    user?: { id?: string; email?: string | null; name?: string | null } | null;
155	  };
156	  const session = value.session?.id && value.session.userId
157	    ? { id: value.session.id, userId: value.session.userId }
158	    : null;
159	  const user = value.user?.id
160	    ? {
161	        id: value.user.id,
162	        email: value.user.email ?? null,
163	        name: value.user.name ?? null,
164	      }
165	    : null;
166	
167	  if (!session || !user) return null;
168	  return { session, user };
169	}
170	
171	export async function resolveBetterAuthSession(
172	  auth: BetterAuthInstance,
173	  req: Request,
174	): Promise<BetterAuthSessionResult | null> {
175	  return resolveBetterAuthSessionFromHeaders(auth, headersFromExpressRequest(req));
176	}
